# 하이브리드 검색: 두 점수를 어떻게 섞나 — RRF 와 점수 가중합 (가상 결과)
bm25 = {"A": 18.2, "B": 11.5, "C": 9.8, "D": 3.1}        # 키워드 점수(크기 제한 없음)
vec  = {"C": 0.91, "E": 0.89, "A": 0.62, "B": 0.60}     # 코사인 유사도(0~1)

def rrf(*lists, k=60):
    s = {}
    for scores in lists:
        for rank, doc in enumerate(sorted(scores, key=scores.get, reverse=True), 1):
            s[doc] = s.get(doc, 0) + 1 / (k + rank)
    return sorted(s, key=s.get, reverse=True)

def raw_sum(a, b):
    docs = set(a) | set(b)
    return sorted(docs, key=lambda d: a.get(d, 0) + b.get(d, 0), reverse=True)

def minmax_mix(a, b, w):
    def norm(x):
        lo, hi = min(x.values()), max(x.values())
        return {d: (v - lo) / (hi - lo) for d, v in x.items()}
    na, nb = norm(a), norm(b)
    docs = set(a) | set(b)
    return sorted(docs, key=lambda d: (1 - w) * na.get(d, 0) + w * nb.get(d, 0), reverse=True)

print("점수 그냥 더하기    :", raw_sum(bm25, vec))
print("RRF (k=60)          :", rrf(bm25, vec))
for w in (0.3, 0.7):
    print(f"정규화 후 벡터 {w:.0%} :", minmax_mix(bm25, vec, w))
# 점수 그냥 더하기    : ['A', 'B', 'C', 'D', 'E']
# RRF (k=60)          : ['A', 'C', 'B', 'E', 'D']
# 정규화 후 벡터 30% : ['A', 'C', 'B', 'E', 'D']
# 정규화 후 벡터 70% : ['C', 'E', 'A', 'B', 'D']

# 한 클러스터를 여러 서비스가 같이 쓸 때: 한 서비스가 몰리면 남의 검색까지 느려진다 (가상 부하)
# 클러스터는 초당 1,000건 처리. 평소 검색 300 + 추천 300 + 광고 200 = 800건/초.
# 10초 중 4~6초째에 추천이 배치 작업으로 초당 1,500건을 쏜다.
CAP = 1000
plan = {"검색": [300] * 10, "추천": [300] * 3 + [1500] * 3 + [300] * 4, "광고": [200] * 10}

def run(quota=None):
    backlog, worst, rejected = 0, 0.0, {s: 0 for s in plan}
    for t in range(10):
        for s, arr in plan.items():
            a = arr[t]
            if quota:                                  # 서비스별 초당 몫을 넘는 요청은 429 로 돌려보낸다
                rejected[s] += max(0, a - quota[s])
                a = min(a, quota[s])
            backlog += a
        backlog = max(0, backlog - CAP)                # 1초 동안 1,000건 처리, 나머지는 공용 줄에 남는다
        worst = max(worst, backlog / CAP)              # 줄 맨 뒤에 선 검색 요청이 기다릴 초
    return worst, backlog, rejected

for name, q in (("격리 없음", None), ("서비스별 몫", {"검색": 450, "추천": 350, "광고": 200})):
    w, left, r = run(q)
    print(f"{name:6s}: 최악 대기 {w:.1f}초, 10초 뒤 남은 줄 {left}건, 429 {r}")
# 격리 없음 : 최악 대기 3.0초, 10초 뒤 남은 줄 2200건, 429 {'검색': 0, '추천': 0, '광고': 0}
# 서비스별 몫: 최악 대기 0.0초, 10초 뒤 남은 줄 0건, 429 {'검색': 0, '추천': 3450, '광고': 0}
